const circleRawSHA='ce7d6e56dd084a5830cc1ee8b4af143b890ab15d8c88ef15377f64e20c673ee7';
const circleAt=Date.parse('2026-10-01T23:02:00Z'), circleObserved=circleAt-10000;
const circleRecord={...record,stationID:'940GZZLUERC',lineID:'circle'};
const circlePath=['PAC','BWT','NHG','HSK','GTR','SKS','SSQ','VIC','SJP','WSM','EMB','TMP','BKF','MSH','CST','MMT','TWH','ALD','LVT','MGT','BBN','FCN','KSX','ESQ','GPS','BST','ERC'].map(id=>'940GZZLU'+id);
const circleRaw=()=>JSON.parse(circleRoundtripBytes);
function circleAsset(raw=circleRaw(),allWeekdays=true){
  const days={Friday:[6],Thursdays:[5],Wednesdays:allWeekdays?[1,2,3,4,7]:[4]};
  const profiles=['Friday','Thursdays','Wednesdays'].map(name=>{const rows=profileJourneys(raw,name);return {name,count:rows.length,sha256:profileFingerprint(rows),weekdays:days[name],originatingServiceDateRanges:[{startDate:'2026-09-30',endDate:'2026-10-02'}]};});
  const proof={schemaVersion:1,publication:{url:'https://tfl.gov.uk/tfl/syndication/feeds/journey-planner-timetables.zip',sha256:sha,capturedAt:'synthetic-runtime-control'},timezone:'Europe/London',bankHolidayDates:[],holidayCoverageStart:'2026-09-30',holidayCoverageEnd:'2026-10-02',entries:[{lineID:'circle',stationID:circleRecord.stationID,status:'qualified',operatingStartDate:'2026-09-30',operatingEndDate:'2026-10-02',nonOperationBankHolidays:true,profiles}]};
  const proofBytes=Buffer.from(JSON.stringify(proof));return {proof,proofBytes,identity:{publicationSHA256:sha,proofRevision:1,proofBodySHA256:crypto.createHash('sha256').update(proofBytes).digest('hex')}};
}
function circleArguments(at=circleAt){return {head:{sha256:sha,observedAt:circleObserved,expiresAt:circleObserved+600000},serviceObservation:{observedAt:circleObserved+3000,expiresAt:circleAt+30000},stationObservation:{observedAt:circleObserved+4000,expiresAt:circleAt+30000},at};}
function circleResource(raw=circleRaw()) {return {...wrap(raw,circleAt),direction:null,headers:headers(circleObserved+6000),bodySHA256:JSON.stringify(raw)===JSON.stringify(circleRaw())?circleRawSHA:crypto.createHash('sha256').update(JSON.stringify(raw)).digest('hex')};}
function circleQualify(raw=circleRaw(),asset=circleAsset(raw),args=circleArguments()){return qualifyTimetable(asset,[circleResource(raw)],circleRecord,args);}
function circlePathMutation(path){const raw=circleRaw();raw.timetable.routes[1].stationIntervals.find(i=>i.id==='1').intervals=path.map(stopId=>({stopId}));return raw;}
function circleSeed(context){
  const event=context.events.find(e=>e.destinationStationID===circleRecord.stationID);assert.ok(event);
  const calendar=context.evidence.rows.find(r=>r.id===event.id);assert.ok(calendar);
  return {schemaVersion:1,stationID:circleRecord.stationID,lineID:'circle',closureEvidence:[],contexts:[{sourceID:'timetable',observedAt:new Date(context.observedAt).toISOString(),expiresAt:new Date(context.expiresAt).toISOString(),publication:context.evidence.publication,rows:[{id:event.id,destinationID:event.destinationStationID,destination:event.destination,departure:new Date(event.time).toISOString(),routeStationIDs:event.routeStationIDs,...calendar}]}]};
}
test('retainedCircleCompleteProfilesQualifyOriginalNodeLoop',()=>{
  assert.equal(crypto.createHash('sha256').update(circleRoundtripBytes).digest('hex'),circleRawSHA);
  const raw=circleRaw(),asset=circleAsset(raw),context=circleQualify(raw,asset);
  for(const p of asset.proof.entries[0].profiles){const rows=profileJourneys(raw,p.name);assert.equal(rows.length,235);assert.equal(profileFingerprint(rows),p.sha256);assert.equal(rows.filter(r=>r.minute===1445 && r.path.at(-1)===circleRecord.stationID).length,1);}
  assert.deepEqual(context.evidence.qualification.map(p=>[p.serviceDay,p.profileName,p.retainedCount]),[['2026-10-01','Thursdays',235],['2026-10-02','Friday',235]]);
  const event=context.events.find(e=>e.destinationStationID===circleRecord.stationID);assert.ok(event);assert.deepEqual(event.routeStationIDs,circlePath);assert.equal(event.time,Date.parse('2026-10-01T23:05:00Z'));assert.equal(event.platform,null);assert.equal(event.direction,null);assert.equal(event.timeEvidence,'scheduledDeparture');assert.equal(context.observedAt,circleObserved);assert.equal(context.expiresAt,circleObserved+600000);
  // Node-only deterministic source and seed controls. Exact Swift equality is
  // REQUIRED separately by the root-owned actual-circle-wire-parity.mjs gate.
  const seed=circleSeed(context),admitted=admitPlannedSeed(seed,circleRecord,circleAt);assert.deepEqual(admitted.errors,[]);const original=admitted.sources.timetable.events.find(e=>e.id===event.id);assert.ok(original);assert.deepEqual(original.routeStationIDs,circlePath);assert.equal(original.time,event.time);assert.equal(original.receivedAt,circleObserved);assert.equal(original.expiresAt,context.expiresAt);assert.equal(original.platform,null);

});

test('circleAdjacentEmptyUnknownAndMalformedPathsRejectAfterMatchingProfile',()=>{
  for(const path of [[],[circleRecord.stationID],[circleRecord.stationID,circleRecord.stationID],['940GZZLUPAC','unknown',circleRecord.stationID],['940GZZLUBNK',circleRecord.stationID],['940GZZLUPAC','']]){
    const raw=circlePathMutation(path),asset=circleAsset(raw);assert.throws(()=>circleQualify(raw,asset));
  }
  const repeatedPath=['940GZZLUPAC',circleRecord.stationID,'940GZZLUBST',circleRecord.stationID],repeated=circlePathMutation(repeatedPath);assert.deepEqual(circleQualify(repeated,circleAsset(repeated)).events.find(e=>e.destinationStationID===circleRecord.stationID).routeStationIDs,repeatedPath);
  const missing=circleRaw(),original=circleAsset(missing);missing.timetable.routes[1].schedules.find(s=>s.name==='Thursdays').knownJourneys.pop();assert.throws(()=>circleQualify(missing,original));
  const broken=circleRaw();broken.timetable.routes[1].schedules.find(s=>s.name==='Thursdays').knownJourneys[0].intervalId=999;assert.throws(()=>circleQualify(broken));
});

test('circleLimitedCalendarAuthorityAndOriginalClockBoundariesRemainStrict',()=>{
  const raw=circleRaw(),literal=circleAsset(raw,false);assert.deepEqual(literal.proof.entries[0].profiles.map(p=>p.weekdays),[[6],[5],[4]]);assert.throws(()=>circleQualify(raw,literal),/unsupportedCalendar/);
  const asset=circleAsset(raw),gap=changedAsset(asset,p=>p.entries[0].status='gap');assert.throws(()=>circleQualify(raw,gap));
  const changedHead=circleArguments();changedHead.head.sha256='b'.repeat(64);assert.throws(()=>circleQualify(raw,asset,changedHead));
  const closed=circleArguments();closed.serviceObservation.expiresAt=circleAt;assert.throws(()=>circleQualify(raw,asset,closed),/unavailable/);
  assert.throws(()=>circleQualify(raw,asset,circleArguments(circleObserved+600001)),/unavailable/);
  const sunday=Date.parse('2026-10-04T00:02:00Z'),args={head:{sha256:sha,...observation(sunday)},serviceObservation:observation(sunday),stationObservation:observation(sunday),at:sunday};assert.throws(()=>qualifyTimetable(asset,[{...circleResource(raw),headers:headers(sunday),completedAt:sunday}],circleRecord,args),/unsupportedCalendar/);
  const context=circleQualify();assert.equal(selectEvents({sources:{timetable:context}},circleRecord,context.expiresAt).length,0);
});

test('circleSeedRouteCalendarExpiryAndPlannerSelfRejectionRemainStrict',()=>{
  const context=circleQualify(),seed=circleSeed(context);assert.deepEqual(admitPlannedSeed(seed,circleRecord,circleAt).errors,[]);
  const event=admitPlannedSeed(seed,circleRecord,circleAt).sources.timetable.events[0];assert.equal(event.platform,null);assert.equal(event.receivedAt,circleObserved);assert.equal(event.expiresAt,circleObserved+600000);assert.deepEqual(event.routeStationIDs,circlePath);
  for(const path of [[circleRecord.stationID],[circleRecord.stationID,circleRecord.stationID],['940GZZLUPAC','unknown',circleRecord.stationID],['940GZZLUBNK',circleRecord.stationID],['940GZZLUPAC'],[],null]){
    const invalid=structuredClone(seed);invalid.contexts[0].rows[0].routeStationIDs=path;assert.ok(admitPlannedSeed(invalid,circleRecord,circleAt).errors.length);
  }
  const wrongCalendar=structuredClone(seed);wrongCalendar.contexts[0].rows[0].weekdays=[6];assert.ok(admitPlannedSeed(wrongCalendar,circleRecord,circleAt).errors.length);
  const badProfile=structuredClone(seed);badProfile.contexts[0].rows[0].profileSHA256='unqualified';assert.ok(admitPlannedSeed(badProfile,circleRecord,circleAt).errors.length);
  const stale=admitPlannedSeed(seed,circleRecord,context.expiresAt);assert.deepEqual(stale.errors,[]);assert.equal(stale.sources.timetable,undefined);
  const jp=structuredClone(seed),source=jp.contexts[0];source.sourceID='journey-planner';source.sourceSHA256='a'.repeat(64);source.expiresAt=new Date(circleObserved+120000).toISOString();delete source.publication;
  const row=source.rows[0];for(const key of ['serviceDay','profileName','profileSHA256','weekdays','serviceMinute','isBankHoliday','originatingServiceDateRanges'])delete row[key];assert.ok(admitPlannedSeed(jp,circleRecord,circleAt).errors.length);
});
